import { useEffect, useState, type HTMLAttributes, type Ref } from 'react';
import { cn } from '../../utils/cn';
import { formatClock, formatCompact, toIsoDuration, toMs, type DateInput, type DurationUnits } from './format';
import { timerVariants, type TimerVariantProps } from './timer.variants';

export type TimerStatus = 'running' | 'paused' | 'stopped';

export interface TimerLabels {
  /** Status text shown (and announced) when paused. */
  paused: string;
  /** Status text shown (and announced) when stopped. */
  stopped: string;
  /** Unit suffixes of the compact format. */
  units: DurationUnits;
}

const DEFAULT_LABELS: TimerLabels = { paused: 'Paused', stopped: 'Stopped', units: { h: 'h', m: 'm', s: 's' } };

export interface TimerProps extends Omit<HTMLAttributes<HTMLSpanElement>, 'className' | 'children'>, Pick<TimerVariantProps, 'size'> {
  className?: string;
  ref?: Ref<HTMLSpanElement>;
  /** When the current run started: a Date, an ISO string or epoch ms. */
  start: DateInput;
  /** Time already accumulated before `start` (ms), e.g. earlier runs of a paused-and-resumed task. */
  offset?: number;
  /** `running` ticks; `paused` and `stopped` freeze the value (at `end` when given). */
  status?: TimerStatus;
  /** When the timer was paused or stopped; makes the frozen value exact. */
  end?: DateInput;
  /** `clock` ("1:02:05", default) or `compact` ("2m 14s"). */
  format?: 'clock' | 'compact';
  /** Shows the status dot (and the paused/stopped text). */
  showStatus?: boolean;
  /**
   * Make changes audible: a polite live region that speaks the compact value every
   * `announceEvery` ms. Off by default (role="timer" is silent).
   */
  announce?: boolean;
  /** Announcement interval in ms (default one minute). */
  announceEvery?: number;
  /** Reference time (epoch ms) for the first render, e.g. the server's, so hydration matches. */
  now?: number;
  /** Visible and announced strings (English defaults). */
  labels?: Partial<TimerLabels>;
}

/**
 * Elapsed time since `start`, live while running, in a `<time dateTime="PT…">` element with
 * role="timer". Paused and stopped states freeze the value and show a status dot.
 */
export function Timer({
  start,
  offset = 0,
  status = 'running',
  end,
  format = 'clock',
  showStatus = true,
  announce = false,
  announceEvery = 60_000,
  now: initialNow,
  labels: labelsProp,
  size,
  className,
  ...props
}: TimerProps) {
  const labels = { ...DEFAULT_LABELS, ...labelsProp };
  const [now, setNow] = useState(() => initialNow ?? Date.now());
  const running = status === 'running';

  useEffect(() => {
    if (!running) return;
    const tick = () => setNow(Date.now());
    const first = window.setTimeout(tick, 0);
    const id = window.setInterval(tick, 1000);
    return () => {
      window.clearTimeout(first);
      window.clearInterval(id);
    };
  }, [running]);

  const startMs = toMs(start) ?? now;
  const until = (!running ? toMs(end) : undefined) ?? now;
  const elapsed = Math.max(0, offset + until - startMs);
  const text = format === 'compact' ? formatCompact(elapsed, labels.units) : formatClock(elapsed);
  const statusText = status === 'paused' ? labels.paused : status === 'stopped' ? labels.stopped : undefined;
  const spokenStep = Math.max(1000, announceEvery);
  const spoken = formatCompact(Math.floor(elapsed / spokenStep) * spokenStep, labels.units);
  const s = timerVariants({ size, status });

  return (
    <span role="timer" aria-live={announce ? 'polite' : 'off'} aria-atomic className={cn(s.root(), className)} data-status={status} {...props}>
      {showStatus && <span aria-hidden className={s.dot()} />}
      <time dateTime={toIsoDuration(elapsed)} aria-hidden={announce || undefined}>
        {text}
      </time>
      {announce && <span className="sr-only">{statusText ? `${spoken}, ${statusText}` : spoken}</span>}
      {showStatus && statusText && (
        <span className={s.status()} aria-hidden={announce || undefined}>
          {statusText}
        </span>
      )}
    </span>
  );
}

export type DateInput = Date | string | number;

/** Epoch ms of a Date, ISO string or epoch number; `undefined` when it cannot be parsed. */
export function toMs(value: DateInput | undefined): number | undefined {
  if (value === undefined) return undefined;
  const ms = value instanceof Date ? value.getTime() : typeof value === 'number' ? value : Date.parse(value);
  return Number.isFinite(ms) ? ms : undefined;
}

export interface DurationUnits {
  h: string;
  m: string;
  s: string;
}

function parts(ms: number) {
  const total = Math.max(0, Math.floor(ms / 1000));
  return { h: Math.floor(total / 3600), m: Math.floor((total % 3600) / 60), s: total % 60 };
}

const pad = (n: number) => String(n).padStart(2, '0');

/** "1:02:05" or "2:14" (minutes and seconds only under an hour). */
export function formatClock(ms: number) {
  const { h, m, s } = parts(ms);
  return h > 0 ? `${h}:${pad(m)}:${pad(s)}` : `${m}:${pad(s)}`;
}

/** "1h 2m", "2m 14s" or "14s": the two most significant units. */
export function formatCompact(ms: number, units: DurationUnits = { h: 'h', m: 'm', s: 's' }) {
  const { h, m, s } = parts(ms);
  if (h > 0) return `${h}${units.h} ${m}${units.m}`;
  if (m > 0) return `${m}${units.m} ${s}${units.s}`;
  return `${s}${units.s}`;
}

/** ISO 8601 duration for `<time dateTime>`, e.g. "PT2M14S". */
export function toIsoDuration(ms: number) {
  const { h, m, s } = parts(ms);
  return `PT${h ? `${h}H` : ''}${m ? `${m}M` : ''}${s || (!h && !m) ? `${s}S` : ''}`;
}

export { Timer, type TimerProps, type TimerStatus, type TimerLabels } from './Timer';
export { formatClock, formatCompact, toIsoDuration } from './format';
export { timerVariants, type TimerVariantProps } from './timer.variants';
export { doc as timerDoc } from './Timer.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const timerVariants = tv({
  slots: {
    root: 'inline-flex items-center gap-1.5 font-mono tabular-nums text-foreground',
    dot: 'size-1.5 shrink-0 rounded-full',
    status: 'font-sans text-muted-foreground',
  },
  variants: {
    size: {
      sm: { root: 'text-[11.5px]', status: 'text-[11px]' },
      md: { root: 'text-[13px]', status: 'text-[12px]' },
      lg: { root: 'text-[20px] font-semibold tracking-tight', dot: 'size-2', status: 'text-[13px] font-normal' },
    },
    status: {
      running: { dot: 'animate-pulse bg-success motion-reduce:animate-none' },
      paused: { root: 'text-muted-foreground', dot: 'bg-warning' },
      stopped: { root: 'text-muted-foreground', dot: 'bg-muted-foreground' },
    },
  },
  defaultVariants: { size: 'md', status: 'running' },
});

export type TimerVariantProps = VariantProps<typeof timerVariants>;

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'Timer',
  group: 'Display',
  status: 'beta',
  description:
    'Elapsed time since a start, live while running ("1:02:05" or compact "2m 14s"), with paused and stopped states. Renders role="timer" around a <time dateTime="PT…"> duration; silent by default, `announce` speaks it politely once a minute.',
  pattern: 'timer',
  keyboard: [['—', 'Not interactive; never takes focus']],
  tokens: ['foreground', 'muted-foreground', 'success', 'warning'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
